void HpaeSessionEffectNode::TapToWriters(HpaePcmBuffer *buffer)
{
    if (buffer == nullptr) {
        AUDIO_DEBUG_LOG("tap skips null buffer");
        return;
    }
    {
        std::lock_guard<std::mutex> lock(tapWriterMutex_);
        // Clear unconditionally so the last writer's removal is not delayed by a stale snapshot reference.
        tapWriterSnapshot_.clear();
        if (tapWriters_.empty()) {
            return;
        }
        for (auto it = tapWriters_.begin(); it != tapWriters_.end();) {
            auto writer = it->lock();
            if (writer == nullptr) {
                it = tapWriters_.erase(it);
                continue;
            }
            tapWriterSnapshot_.push_back(writer);
            ++it;
        }
    }
    // Callbacks run outside the lock so writers may take their own locks without lock-order coupling.
    for (const auto &writer : tapWriterSnapshot_) {
        writer->OnTapData(reinterpret_cast<const int8_t *>(buffer->GetPcmDataBuffer()), buffer->DataSize());
    }
}

bool RendererInServer::IsDupStreamUpToDate(int32_t innerCapId)
{
    if (!captureInfos_.count(innerCapId) || !captureInfos_[innerCapId].isInnerCapEnabled) {
        return false;
    }
    // A concurrent enable raced the SE rebuild; a format mismatch must not survive the switch.
    if (captureInfos_[innerCapId].isSeFormatStream == hasSessionEffect_.load()) {
        AUDIO_INFO_LOG("InnerCap is already enabled,id:%{public}d", innerCapId);
        return true;
    }
    // Caller must hold dupMutex_, so the Handle variant is used: it does not lock again.
    int32_t ret = DisableInnerCapHandle(innerCapId);
    AUDIO_WARNING_LOG("dup stream format mismatch, rebuild, innerCapId %{public}d, ret %{public}d",
        innerCapId, ret);
    return false;
}

// A stranded id must not mute the rest, and the caller must still see the first failure.
int32_t firstError = SUCCESS;
for (int32_t innerCapId : enabledIds) {
    // Drop the previous hook first so a stale writer never touches the rebuilt stream.
    UnregisterSessionEffectTapWriterForId(innerCapId);
    int32_t ret = DisableInnerCap(innerCapId);
    firstError = (firstError == SUCCESS) ? ret : firstError;
    if (ret != SUCCESS) {
        AUDIO_WARNING_LOG("disable failed, innerCapId %{public}d", innerCapId);
        continue;
    }
}
// Must land after the teardown and before the rebuild: InitDupStream picks the format from this
// flag and OtherStreamEnqueue resumes the client copy only when it is false.
hasSessionEffect_.store(toSessionEffectFormat);
for (int32_t innerCapId : enabledIds) {
    int32_t ret = EnableInnerCap(innerCapId);
    firstError = (firstError == SUCCESS) ? ret : firstError;
    if (ret != SUCCESS) {
        AUDIO_WARNING_LOG("enable failed, innerCapId %{public}d", innerCapId);
        continue;
    }
}
return firstError;

void SessionEffectTapWriter::OnTapData(const int8_t *inputData, size_t dataLen)
{
    auto callbacks = callbacks_.lock();
    if (callbacks == nullptr) {
        // Silent by contract: no logging on the realtime thread, only a test-visible counter.
        releasedDropCount_.fetch_add(1);
        return;
    }
    auto &ring = callbacks->GetDupRingBuffer();
    CHECK_AND_RETURN(ring != nullptr);
    // Enqueue treats dataPtr as a read-only memcpy source.
    BufferWrap wrap = {reinterpret_cast<uint8_t *>(const_cast<int8_t *>(inputData)), dataLen};
    OptResult result = ring->Enqueue(wrap);
    if (result.ret != OPERATION_SUCCESS) {
        uint32_t drops = enqueueDropCount_.fetch_add(1) + 1;
        if (drops == 1 || drops % SE_TAP_DROP_LOG_PERIOD == 0) {
            AUDIO_WARNING_LOG("tap ring enqueue failed, drop, innerCapId %{public}d, drop %{public}u",
                innerCapId_, drops);
        }
    }
    callbacks->SetFirstWriteDataFlag(false);
}

void RendererInServer::TeardownSessionEffectTapWriters()
{
    std::vector<std::shared_ptr<IHpaeInnerCapTapWriter>> writers;
    {
        std::lock_guard<std::mutex> lock(sessionEffectTapWriterMutex_);
        writers.reserve(sessionEffectTapWriters_.size());
        for (auto &entry : sessionEffectTapWriters_) {
            writers.emplace_back(entry.second);
        }
        sessionEffectTapWriters_.clear();
    }
    // Up to 2s per writer (SendRequestSync timeout); called outside the mutex so
    // concurrent enable/disable paths never wait on engine round-trips.
    for (auto &writer : writers) {
        // The stream is going away; on the ReleasePostProcess pass the engine session is
        // already destroyed and a session-not-found error is expected and benign.
        HPAE::IHpaeManager::GetHpaeManager().UnregisterSessionEffectTapWriter(streamIndex_, writer);
    }
    AUDIO_INFO_LOG("dropped %{public}zu tap writers", writers.size());
}
